function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Spreadsheet' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with Spreadsheet(rows).';
  const rows = args[0][0];
  if (!Number.isInteger(rows) || rows < 1 || rows > 1000) return 'rows is between 1 and 1000.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls follow the constructor.';
  const isCell = (text) => typeof text === 'string' && /^[A-Z][1-9]\d*$/.test(text) && Number(text.slice(1)) <= rows;
  const isNumber = (text) => /^(0|[1-9]\d*)$/.test(text) && Number(text) <= 100000;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'setCell') {
      if (a.length !== 2 || !isCell(a[0])) return `setCell needs a cell from A1 to Z${rows}.`;
      if (!Number.isInteger(a[1]) || a[1] < 0 || a[1] > 100000) return 'value is between 0 and 10^5.';
    } else if (operations[i] === 'resetCell') {
      if (a.length !== 1 || !isCell(a[0])) return `resetCell needs a cell from A1 to Z${rows}.`;
    } else if (operations[i] === 'getValue') {
      const parts = a.length === 1 && typeof a[0] === 'string' ? /^=([^+]+)\+([^+]+)$/.exec(a[0]) : null;
      if (!parts || !parts.slice(1).every(part => isCell(part) || isNumber(part))) return `A formula looks like "=X+Y", where X and Y are cells from A1 to Z${rows} or numbers from 0 to 10^5.`;
    } else {
      return 'Only setCell, resetCell and getValue can follow the constructor.';
    }
  }
  return null;
}

