class Spreadsheet {
  constructor(rows) {
    this.cells = new Map();
  }

  setCell(cell, value) {
    this.cells.set(cell, value);
  }

  resetCell(cell) {
    this.cells.delete(cell);
  }

  getValue(formula) {
    const [left, right] = formula.slice(1).split('+');
    return this.operand(left) + this.operand(right);
  }

  operand(token) {
    if (token[0] >= 'A' && token[0] <= 'Z') {
      return this.cells.get(token) ?? 0;
    }
    return Number(token);
  }
}

