class Spreadsheet {
  constructor(rows) {
    // A full grid: row r (1-based) and column letter c live at grid[r][c - 'A'].
    this.grid = Array.from({ length: rows + 1 }, () => new Array(26).fill(0));
  }
  setCell(cell, value) {
    this.grid[parseInt(cell.slice(1), 10)][cell.charCodeAt(0) - 65] = value;
  }
  resetCell(cell) {
    this.setCell(cell, 0);
  }
  getValue(formula) {
    const match = /^=(\w+)\+(\w+)$/.exec(formula);
    const read = (part) => /^\d+$/.test(part) ? parseInt(part, 10) : this.grid[parseInt(part.slice(1), 10)][part.charCodeAt(0) - 65];
    return read(match[1]) + read(match[2]);
  }
}

