function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  // Twelve rows let names such as A1, A11 and A12 meet in small cases.
  const rows = large ? int(1, 1000) : [1, 2, 12][int(0, 2)];
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const anyCell = () => letters[int(0, 25)] + int(1, rows);
  // Most calls use a small pool of cells, so formulas often read cells that were set or reset.
  const pool = Array.from({ length: large ? 60 : int(1, 4) }, anyCell);
  const cell = () => rand() < 0.8 ? pool[int(0, pool.length - 1)] : anyCell();
  const value = () => [0, int(0, 9), int(0, 100000), 100000][int(0, 3)];
  const operand = () => rand() < 0.6 ? cell() : String(value());
  const operations = ['Spreadsheet'];
  const args = [[rows]];
  const calls = large ? 499 : int(1, 12);
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < 0.35) {
      operations.push('setCell');
      args.push([cell(), value()]);
    } else if (roll < 0.5) {
      operations.push('resetCell');
      args.push([cell()]);
    } else {
      operations.push('getValue');
      args.push([`=${operand()}+${operand()}`]);
    }
  }
  return [operations, args];
}
